      '13000000-0000-0000-0000-000000000029',
      '13000000-0000-0000-0000-000000000030',
      '13000000-0000-0000-0000-000000000031',
      '13000000-0000-0000-0000-000000000032',
      '13000000-0000-0000-0000-000000000033',
      '13000000-0000-0000-0000-000000000034',
      '13000000-0000-0000-0000-000000000035',
      '13000000-0000-0000-0000-000000000036',
      '13000000-0000-0000-0000-000000000037',
      '13000000-0000-0000-0000-000000000038',
      '13000000-0000-0000-0000-000000000039',
      '13000000-0000-0000-0000-000000000040',
      '13000000-0000-0000-0000-000000000041',
      '13000000-0000-0000-0000-000000000042',
      '13000000-0000-0000-0000-000000000043',
      '13000000-0000-0000-0000-000000000044',
      '13000000-0000-0000-0000-000000000045',
      '13000000-0000-0000-0000-000000000046',
      '13000000-0000-0000-0000-000000000047',
      '13000000-0000-0000-0000-000000000048'
  )
  AND NOT EXISTS (
      SELECT 1 FROM cart_items
      WHERE cart_items.variant_id = variant_option_values.variant_id
  );
DELETE FROM variant_option_values
WHERE variant_id::text LIKE '13000000-%';

DELETE FROM product_variants
WHERE id::text LIKE '13000000-%'
  AND NOT EXISTS (
      SELECT 1 FROM cart_items
      WHERE cart_items.variant_id = product_variants.id
  );
UPDATE product_variants
SET active = false,
    updated_at = now()
WHERE id::text LIKE '13000000-%'
  AND id NOT IN (
      '13000000-0000-0000-0000-000000000001',
      '13000000-0000-0000-0000-000000000002',
      '13000000-0000-0000-0000-000000000003',
      '13000000-0000-0000-0000-000000000004',
