      '13000000-0000-0000-0000-000000000046',
      '13000000-0000-0000-0000-000000000047',
      '13000000-0000-0000-0000-000000000048'
  );
DELETE FROM product_option_values
WHERE id::text LIKE '12000000-%'
  AND NOT EXISTS (
      SELECT 1 FROM variant_option_values
      WHERE variant_option_values.option_value_id = product_option_values.id
  );
DELETE FROM product_option_groups
WHERE id::text LIKE '11000000-%'
  AND NOT EXISTS (
      SELECT 1 FROM variant_option_values
      WHERE variant_option_values.group_id = product_option_groups.id
  );
DELETE FROM product_images
WHERE id::text LIKE '10000000-0000-0002-%';

